import { spawn } from 'node:child_process';
const [,, mode, marker] = process.argv;
const p = spawn('/harness-state/.gbrain/hook-launcher/gbrain-hook',
  ['/harness-state/.bun/bin/gbrain','serve','--surface','starter','--advertise','verbs'],
  { stdio: ['pipe','pipe','inherit'] });
let buf = '', id = 0; const waiters = {};
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) {
  const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue;
  try { const m = JSON.parse(line); if (m.id != null && waiters[m.id]) waiters[m.id](m); } catch {} } });
const rpc = (method, params) => new Promise(r => { const n = ++id; waiters[n] = r;
  p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const call = async (name, args) => { const r = await rpc('tools/call', { name, arguments: args });
  console.log(`--- ${name} ->`, JSON.stringify(r.result ?? r.error).slice(0, 1500)); return r; };
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('tools:', tl.result.tools.map(t => t.name).join(', '));
if (mode === 'schema') for (const t of tl.result.tools.filter(t => ['remember','recall','forget'].includes(t.name))) console.log(t.name, JSON.stringify(t.inputSchema).slice(0, 1200));
if (mode === 'remember') await call('remember', { fact: `GBrain install-check marker ${marker}: memory round trip test, safe to delete.`, entity: 'gbrain-install-check', provenance: 'install-check', content_origin: 'inferred' });
if (mode === 'recall') { await call('recall', { entity: 'gbrain-install-check' }); }
if (mode === 'forget') await call('forget', { fact_id: marker, reason: 'install-check cleanup' });
p.stdin.end(); p.kill();
EOF
cd /tmp && node /tmp/gbrain-verify/mcp.mjs schema

